// FILE: frontend/src/LogList.js
//
// --- VERSION 1.1.0 ---
// - Adding LogPlayback feature
// -----------------------------

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { groupLogsIntoTrips } from '../../utils/tripUtils';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const LogList = () => {
    const [logGroups, setLogGroups] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [viewMode, setViewMode] = useState('trips'); // 'trips' or 'individual'

    useEffect(() => {
        axios.get(`${API_URL}/api/logs`)
            .then(response => {
                const grouped = groupLogsIntoTrips(response.data);
                setLogGroups(grouped);
                setLoading(false);
            })
            .catch(err => {
                console.error("Error fetching logs:", err);
                setError('Failed to fetch logs.');
                setLoading(false);
            });
    }, []);

    const renderLogItem = (log) => (
        <li key={log.id} className="flex items-center justify-between p-3 bg-base-200 rounded-lg">
            <div className="flex-1">
                <Link to={`/logs/${log.id}`} className="font-semibold text-primary hover:underline">
                    {log.filename}
                </Link>
                <div className="text-xs text-base-content/70">
                    {new Date(log.timestamp * 1000).toLocaleString()}
                </div>
            </div>
            <div className="flex items-center gap-2">
              {/* Add a button/link to the new playback page */}
              <Link to={`/playback/${log.id}`} 
                className="btn btn-sm btn-outline btn-accent"
                title="Open Playback View"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                Playback
              </Link>
              <Link to={`/logs/${log.id}`} className="btn btn-sm btn-secondary">Details</Link>
            </div>
        </li>
    );

    if (loading) return <div>Loading logs...</div>;
    if (error) return <div className="text-error">{error}</div>;

    return (
        <div className="container mx-auto p-4">
            <h1 className="text-3xl font-bold mb-4">Log Files</h1>
            <div className="tabs tabs-boxed mb-4">
                <button className={`tab ${viewMode === 'trips' ? 'tab-active' : ''}`} onClick={() => setViewMode('trips')}>
                    Group by Trip
                </button>
                <button className={`tab ${viewMode === 'individual' ? 'tab-active' : ''}`} onClick={() => setViewMode('individual')}>
                    Individual Logs
                </button>
            </div>

            {viewMode === 'trips' ? (
                <div className="space-y-4">
                    {logGroups.map(group => (
                        <div key={group.groupId} className="card bg-base-100 shadow-xl">
                            <div className="card-body">
                                <h2 className="card-title">
                                    <Link to={`/trip-groups/${group.groupId}`} className="text-accent hover:underline">
                                        Trip Group starting {new Date(group.logs[0].timestamp * 1000).toLocaleString()}
                                    </Link>
                                </h2>
                                <p>{group.logs.length} logs in this trip.</p>
                                <ul className="space-y-2 mt-2">
                                    {group.logs.map(renderLogItem)}
                                </ul>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <ul className="space-y-2">
                    {logGroups.flatMap(g => g.logs).sort((a, b) => b.timestamp - a.timestamp).map(renderLogItem)}
                </ul>
            )}
        </div>
    );
};

export default LogList;
